package viewpoint.render;
public final class ModelDraws{zombie.core.skinnedmodel.model.ModelMesh[] meshes=new zombie.core.skinnedmodel.model.ModelMesh[16];float[] values=new float[16*68];int[] palette=new int[16];float[] palettes=new float[64*12];int bones;private int count;public int count(){return count;}public void add(zombie.core.skinnedmodel.model.ModelMesh m,float[] matrix,int p){meshes[count]=m;System.arraycopy(matrix,0,values,count*68,16);palette[count]=p;count++;}public void skin(float[] data,int active){System.arraycopy(data,0,palettes,0,data.length);bones=active;}public float[] matrices(){return values;}public void clear(){count=0;}}
